using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionDeterminismTests { [Theory][InlineData("orion")][InlineData("leo")][InlineData("conjunction")] public void Independently_reconstructed_graphs_are_byte_deterministic(string name){DocumentaryMediaProjectionRequest Make()=>name=="orion"?DocumentaryMediaProjectionFixture.Orion():name=="leo"?DocumentaryMediaProjectionFixture.Leo():DocumentaryMediaProjectionFixture.Conjunction();var a=Make();var b=Make();Assert.NotSame(a,b);Assert.Equal(DocumentaryMediaProjectionFixture.Json(a),DocumentaryMediaProjectionFixture.Json(b));Assert.Equal(DocumentaryMediaProjectionFixture.Json(new DocumentaryMediaProjector().Project(a)),DocumentaryMediaProjectionFixture.Json(new DocumentaryMediaProjector().Project(b)));} }
